    "language": "kotlin",
    "description": "Modelos de perfis de transmissão: Economia, Equilibrado e Baixa Latência",
    "content": "package com.touchscreenlink.app.model\n\nenum class StreamProfile(\n    val title: String,\n    val description: String,\n    val width: Int,\n    val height: Int,\n    val fps: Int,\n    val bitrateKbps: Int,\n    val codecProfile: String,\n    val gopFrames: Int,\n    val keyframeIntervalSec: Float,\n    val allowBFrames: Boolean\n) {\n    ECONOMY(\n        title = \"Economia\",\n        description = \"1280 × 720 @ 30 FPS, 2.500 kbps, H.264 Baseline, GOP 60 (~2s keyframe). Mínimo consumo de bateria e rede.\",\n        width = 1280,\n        height = 720,\n        fps = 30,\n        bitrateKbps = 2500,\n        codecProfile = \"Baseline\",\n        gopFrames = 60,\n        keyframeIntervalSec = 2.0f,\n        allowBFrames = false\n    ),\n    BALANCED(\n        title = \"Equilibrado\",\n        description = \"1920 × 1080 @ 60 FPS (fallback adaptativo para 45 FPS), 6.500 kbps, H.264 Main, GOP 120 (~2s keyframe).\",\n        width = 1920,\n        height = 1080,\n        fps = 60,\n        bitrateKbps = 6500,\n        codecProfile = \"Main\",\n        gopFrames = 120,\n        keyframeIntervalSec = 2.0f,\n        allowBFrames = false\n    ),\n    LOW_LATENCY(\n        title = \"Baixa Latência\",\n        description = \"1600 × 900 @ 60 FPS, 8.000 kbps, GOP 60 (~1s keyframe), zero B-frames e sem filas intermediárias.\",\n        width = 1600,\n        height = 900,\n        fps = 60,\n        bitrateKbps = 8000,\n        codecProfile = \"High\",\n        gopFrames = 60,\n        keyframeIntervalSec = 1.0f,\n        allowBFrames = false\n    )\n}\n\ndata class StreamConfig(\n    val profile: StreamProfile = StreamProfile.BALANCED,\n    val keepScreenOn: Boolean = true,\n    val lowLatencyMode: Boolean = true,\n    val enableHardwareAcceleration: Boolean = true\n) {\n    companion object {\n        val DEFAULT = StreamConfig()\n    }\n}\n"
